const EMPTY_SHAPE_UTILS_ARRAY = [] as const
const EMPTY_BINDING_UTILS_ARRAY = [] as const
const EMPTY_ASSET_UTILS_ARRAY = [] as const
const EMPTY_TOOLS_ARRAY = [] as const
/** @internal */
export const TL_CONTAINER_CLASS = 'tl-container'

/** @public @react */
export const TldrawEditor = memo(function TldrawEditor({
	store,
	components,
	className,
	user: _user,
	options: _options,
	// eslint-disable-next-line @typescript-eslint/no-deprecated
	textOptions: _textOptions,
	// eslint-disable-next-line @typescript-eslint/no-deprecated
	deepLinks: _deepLinks,
	...rest
}: TldrawEditorProps) {
	// Register custom colors and fonts before effects run. For external stores,
	// users should also pass themes to createTLStore so they are
	// registered before data is loaded into the store.
	const resolvedThemes = resolveThemes(rest.themes)
	registerColorsFromThemes(resolvedThemes)
	registerFontsFromThemes(resolvedThemes)

	const [container, setContainer] = useState<HTMLElement | null>(null)
	const [portalHost, setPortalHost] = useState<HTMLElement | null>(null)
	const user = useMemo(() => _user ?? createTLCurrentUser(), [_user])

	const ErrorFallback =
		components?.ErrorFallback === undefined ? DefaultErrorFallback : components?.ErrorFallback

	// Merge deprecated props with options
	// options values take precedence over the deprecated props
	const mergedOptions = useMemo(() => {
		let result = _options
		if (_textOptions) {
			result = { ...result, text: result?.text ?? _textOptions }
		}
		if (_deepLinks !== undefined) {
			result = { ...result, deepLinks: result?.deepLinks ?? _deepLinks }
		}
		return result
	}, [_options, _textOptions, _deepLinks])

	// apply defaults. if you're using the bare @tldraw/editor package, we
	// default these to the "tldraw zero" configuration. We have different
	// defaults applied in tldraw.
	const withDefaults = {
		...rest,
		shapeUtils: rest.shapeUtils ?? EMPTY_SHAPE_UTILS_ARRAY,
		bindingUtils: rest.bindingUtils ?? EMPTY_BINDING_UTILS_ARRAY,
		assetUtils: rest.assetUtils ?? EMPTY_ASSET_UTILS_ARRAY,
		tools: rest.tools ?? EMPTY_TOOLS_ARRAY,
		components,
		options: useShallowObjectIdentity(mergedOptions),
	}

	return (
		<div
			ref={setContainer}
			data-tldraw={version}
			draggable={false}
			className={classNames(`${TL_CONTAINER_CLASS} tl-theme__light`, className)}
			tabIndex={-1}
			role="application"
			aria-label={_options?.branding ?? 'tldraw'}
		>
			<OptionalErrorBoundary
				fallback={ErrorFallback}
				onError={(error) => annotateError(error, { tags: { origin: 'react.tldraw-before-app' } })}
			>
				{container && (
					<LicenseProvider licenseKey={rest.licenseKey}>
						<ContainerProvider container={container}>
							<EditorPortalProvider host={portalHost}>
								<EditorComponentsProvider overrides={components}>
									{store ? (
										store instanceof Store ? (
											// Store is ready to go, whether externally synced or not
											<TldrawEditorWithReadyStore {...withDefaults} store={store} user={user} />
										) : (
											// Store is a synced store, so handle syncing stages internally
											<TldrawEditorWithLoadingStore {...withDefaults} store={store} user={user} />
										)
									) : (
										// We have no store (it's undefined) so create one and possibly sync it

	store,
	user,
	...rest
}: Required<
	TldrawEditorProps & { store: TLStoreWithStatus; user: TLCurrentUser },
	'shapeUtils' | 'bindingUtils' | 'assetUtils' | 'tools'
>) {
	const container = useContainer()

	useLayoutEffect(() => {
		if (user.userPreferences.get().colorScheme === 'dark') {
			container.classList.remove('tl-theme__light')
			container.classList.add('tl-theme__dark')
		}
	}, [container, user])

	const { LoadingScreen } = useEditorComponents()

	switch (store.status) {
		case 'error': {
			// for error handling, we fall back to the default error boundary.
			// if users want to handle this error differently, they can render
			// their own error screen before the TldrawEditor component
			throw store.error
		}
		case 'loading': {
			return LoadingScreen ? <LoadingScreen /> : null
		}
		case 'not-synced': {
			break
		}
		case 'synced-local': {
			break
		}
		case 'synced-remote': {
			break
		}
	}

	return <TldrawEditorWithReadyStore {...rest} store={store.store} user={user} />
})

const noAutoFocus = () => getGlobalDocument().location.search.includes('tldraw_preserve_focus')

function TldrawEditorWithReadyStore({
	onMount,
	children,
	store,

	assetUtils,
	overlayUtils,
	user,
	initialState,
	autoFocus = true,
	// eslint-disable-next-line @typescript-eslint/no-deprecated
	cameraOptions,
	options,
	licenseKey,
	getShapeVisibility,
	colorScheme,
	assetUrls,
	themes,
	initialTheme,
}: Required<
	TldrawEditorProps & {
		store: TLStore
		user: TLCurrentUser
	},
	'shapeUtils' | 'bindingUtils' | 'assetUtils' | 'tools'
>) {
	const { ErrorFallback } = useEditorComponents()
	const container = useContainer()
	const licenseManager = useLicenseContext()

	const [editor, setEditor] = useRefState<Editor | null>(null)

	const canvasRef = useRef<HTMLDivElement | null>(null)

	const _deepLinks = options?.deepLinks
	const deepLinks = useShallowObjectIdentity(_deepLinks === true ? {} : _deepLinks)

	// props in this ref can be changed without causing the editor to be recreated.
	const editorOptionsRef = useRef({
		// for these, it's because they're only used when the editor first mounts:
		autoFocus: autoFocus && !noAutoFocus(),
		initialState,
		colorScheme,

		// for these, it's because we keep them up to date in a separate effect:
		cameraOptions,
		deepLinks,
		themes,
		initialTheme,
	})

	useLayoutEffect(() => {
		editorOptionsRef.current = {
			autoFocus: autoFocus && !noAutoFocus(),
			initialState,
			colorScheme,
			cameraOptions,
			deepLinks,
			themes,
			initialTheme,
		}
	}, [autoFocus, initialState, colorScheme, cameraOptions, deepLinks, themes, initialTheme])

	useLayoutEffect(
		() => {
			const {
				autoFocus,
				initialState,
				colorScheme: initColorScheme,
				cameraOptions,
				deepLinks,
				themes,
				initialTheme,
			} = editorOptionsRef.current
			const editor = new Editor({
				store,
				shapeUtils,
				bindingUtils,
				assetUtils,
				overlayUtils,
				tools,
				getContainer: () => container,
				user,
				initialState,
				// we should check for some kind of query parameter that turns off autofocus
				autoFocus,
				cameraOptions,
				options,
				licenseKey,
				getShapeVisibility,
				colorScheme: initColorScheme,
				fontAssetUrls: assetUrls?.fonts,
				themes: themes,
				initialTheme: initialTheme,
			})
			editor.licenseManager = licenseManager

			editor.updateViewportScreenBounds(canvasRef.current ?? container)

			// Use the ref here because we only want to do this once when the editor is created.
			// We don't want changes to the urlStateSync prop to trigger creating new editors.
			if (deepLinks) {
				if (!deepLinks?.getUrl) {
					// load the state from window.location
					editor.navigateToDeepLink(deepLinks)
				} else {
					// load the state from the provided URL
					editor.navigateToDeepLink({ ...deepLinks, url: deepLinks.getUrl(editor) })
				}
			}

			setEditor(editor)

			return () => {
				editor.dispose()
			}
		},
		// if any of these change, we need to recreate the editor.
		[
			assetUtils,
			bindingUtils,
			colorScheme,
			container,
			options,
			overlayUtils,
			shapeUtils,
			store,
			tools,
			user,
			setEditor,
			licenseKey,
			licenseManager,
			getShapeVisibility,
			assetUrls,
		]
	)

	useLayoutEffect(() => {
		if (!editor) return
		if (deepLinks) {
			return editor.registerDeepLinkListener(deepLinks)
		}
	}, [editor, deepLinks])

	// keep the editor up to date with the latest camera options
	// options.cameraOptions takes precedence over the deprecated cameraOptions prop
	useLayoutEffect(() => {
		if (editor && (cameraOptions || options?.camera)) {
			editor.setCameraOptions({ ...cameraOptions, ...options?.camera })
		}
	}, [editor, cameraOptions, options?.camera])

	// keep the editor up to date with the latest theme definitions
	useLayoutEffect(() => {
		if (editor && themes) {
			for (const def of Object.values(themes) as TLTheme[]) {
				editor.updateTheme(def)
			}
		}
	}, [editor, themes])

	useLayoutEffect(() => {
		if (editor && initialTheme) {
			editor.setCurrentTheme(initialTheme)
		}
	}, [editor, initialTheme])

	const crashingError = useSyncExternalStore(
		useCallback(
			(onStoreChange) => {
				if (editor) {
					editor.on('crash', onStoreChange)
					return () => editor.off('crash', onStoreChange)
				}
				return () => {
					// noop
				}
			},
			[editor]
		),
		() => editor?.getCrashingError() ?? null
	)

	// For our examples site, we want autoFocus to be true on the examples site, but not
	// when embedded in our docs site. If present, the `tldraw_preserve_focus` search param
	// overrides the `autoFocus` prop and prevents the editor from focusing immediately,
	// however here we also add some logic to focus the editor when the user clicks
	// on it and unfocus it when the user clicks away from it.
	useEffect(
		function handleFocusOnPointerDownForPreserveFocusMode() {
			if (!editor) return

			function handleFocusOnPointerDown() {
				if (!editor) return
				editor.focus()
			}

			function handleBlurOnPointerDown() {
				if (!editor) return
				editor.blur()
			}

			if (autoFocus && noAutoFocus()) {
				const container = editor.getContainer()
				container.addEventListener('pointerdown', handleFocusOnPointerDown)

			return () => {
				container.removeEventListener('pointerdown', handleFocusOnPointerDown)
				container.ownerDocument.body.removeEventListener('pointerdown', handleBlurOnPointerDown)
			}
		}
	},
	[editor, autoFocus]
)

const [_fontLoadingState, setFontLoadingState] = useState<{
	editor: Editor
	isLoaded: boolean
} | null>(null)
let fontLoadingState = _fontLoadingState
if (editor !== fontLoadingState?.editor) {
	fontLoadingState = null
}
useLayoutEffect(() => {
	if (!editor) return

.loadRequiredFontsForCurrentPage(editor.options.maxFontsToLoadBeforeRender)
.finally(() => {
	if (isCancelled) return
	setFontLoadingState({ editor, isLoaded: true })
})

if (!editor || !fontLoadingState?.isLoaded) {
	return (
		<>
			{LoadingScreen && <LoadingScreen />}
			<div className="tl-canvas" ref={canvasRef} />
		</>
	)
}

return (
	// the top-level tldraw component also renders an error boundary almost
	// identical to this one. the reason we have two is because this one has
	// access to `App`, which means that here we can enrich errors with data
	// from app for reporting, and also still attempt to render the user's
	// document in the event of an error to reassure them that their work is
	// not lost.
	<OptionalErrorBoundary
		fallback={ErrorFallback as any}
		onError={(error) =>
			editor.annotateError(error, { origin: 'react.tldraw', willCrashApp: true })
		}
	>
		{crashingError ? (
			<Crash crashingError={crashingError} />
		) : (
			<EditorProvider editor={editor}>
				<Layout onMount={onMount}>
					{children ?? (Canvas ? <Canvas key={editor.contextId} /> : null)}
					<Watermark />
				</Layout>
			</EditorProvider>
		)}
